<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref,onMounted,watch} from 'vue'
import {request} from '../api'
import FolderSelect from './FolderSelect.vue'
const props=defineProps<{items:{id:string;revision:number}[]}>(),emit=defineEmits<{(e:'changed'):void}>()
type Rule={id?:string;name:string;enabled:boolean;date_source:'uploaded'|'captured';fallback:'uploaded'|'unknown';granularity:'year'|'month'|'day';by_type:boolean;parent_id:string|null;revision?:number}
const blank=():Rule=>({name:'',enabled:false,date_source:'uploaded',fallback:'unknown',granularity:'month',by_type:false,parent_id:null})
const rules=ref<Rule[]>([]),draft=ref<Rule>(blank()),plan=ref<{id:string;items:{id:string;filename:string;path:string[]}[]}|null>(null),busy=ref(false),message=ref(''),saved=ref('')
async function load(){rules.value=await request('/admin/organization/rules')}
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await fn()}catch(e){message.value=String(e)}finally{busy.value=false}}
function select(e:Event){draft.value=structuredClone(rules.value.find(x=>x.id===((e.target as HTMLSelectElement).value))||blank());plan.value=null;saved.value=JSON.stringify(draft.value)}
async function save(){if(draft.value.enabled&&!await confirmAction('启用后，新上传且未指定文件夹的图片将自动逻辑归档；不扫描、不删除旧文件。确认启用？'))return;await work(async()=>{const d=draft.value;draft.value=await request('/admin/organization/rules'+(d.id?'/'+d.id:''),{method:d.id?'PUT':'POST',body:JSON.stringify({...d,id:undefined,revision:undefined,parent_id:d.parent_id||null,...(d.id?{expected_revision:d.revision}:{})})});plan.value=null;saved.value=JSON.stringify(draft.value);await load();message.value='规则已保存；旧图片未移动'})}
async function preview(){await work(async()=>{if(!draft.value.id)throw new Error('请先保存规则');if(JSON.stringify(draft.value)!==saved.value)throw new Error('请先保存规则变更再预览');if(!props.items.length)throw new Error('请先在媒体库选择图片');plan.value=await request('/admin/organization/rules/'+draft.value.id+'/preview',{method:'POST',body:JSON.stringify({items:props.items.map(i=>({id:i.id,expected_revision:i.revision}))})})})}
async function execute(){if(!plan.value||!await confirmAction('确认按预览归档 '+plan.value.items.length+' 张图片？只修改逻辑文件夹，不移动或删除原图。'))return;await work(async()=>{const r=await request('/admin/organization/plans/'+plan.value!.id+'/execute',{method:'POST',body:JSON.stringify({confirmation:'确认逻辑归档'})});message.value='已归档 '+r.count+' 张；重复请求不会再次移动';plan.value=null;emit('changed')})}
watch(draft,()=>plan.value=null,{deep:true})
watch(()=>props.items.map(x=>x.id+':'+x.revision).join(','),()=>plan.value=null)
onMounted(()=>void work(load))
</script>
<template><details class="card archive-rules"><summary>自动归档规则与批量预览</summary><p>默认关闭。启用后只处理之后未指定文件夹的新上传；旧图片必须选择、预览并确认。上传日期使用 UTC，拍摄日期缺失时按所选回退规则处理。</p><label>编辑规则<select @change="select" :disabled="busy"><option value="">新规则</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}} · {{r.enabled?'启用':'停用'}}</option></select></label><fieldset :disabled="busy"><label>名称<input v-model="draft.name" maxlength="100"/></label><label><input type="checkbox" v-model="draft.enabled"/>启用新上传自动归档</label><label>日期来源<select v-model="draft.date_source"><option value="uploaded">上传日期</option><option value="captured">EXIF 拍摄日期</option></select></label><label>拍摄日期缺失<select v-model="draft.fallback"><option value="unknown">归入拍摄日期未知</option><option value="uploaded">回退上传日期</option></select></label><label>层级<select v-model="draft.granularity"><option value="year">年</option><option value="month">年 / 月</option><option value="day">年 / 月 / 日</option></select></label><label><input type="checkbox" v-model="draft.by_type"/>再按服务端验证的文件类型分组</label><label>目标父文件夹<FolderSelect :model-value="draft.parent_id||''" @update:model-value="draft.parent_id=$event||null"/></label><button type="button" :disabled="!draft.name.trim()" @click="save">保存规则</button><button type="button" :disabled="!draft.id||!items.length" @click="preview">预览所选 {{items.length}} 张</button></fieldset><section v-if="plan"><h4>归档预览</h4><ul><li v-for="p in plan.items" :key="p.id">{{p.filename}} → {{p.path.join(' / ')}}</li></ul><button type="button" :disabled="busy||!draft.enabled" @click="execute">确认执行逻辑归档</button><p v-if="!draft.enabled">请先启用并保存规则，再重新预览。</p><button type="button" class="quiet" @click="plan=null">取消预览</button></section><p v-if="message" role="status">{{message}}</p></details></template>
<style scoped>.archive-rules fieldset{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:12px;min-width:0}.archive-rules input,.archive-rules select{max-width:100%}.archive-rules li{overflow-wrap:anywhere}</style>
